INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein dezentrales Netzwerk immer schneller als ein Client-Server-Modell?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Teilnehmern ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil eines solchen Netzwerks?', 3, '[{"text": "Dezentralisierung", "correct": true, "because": "Keine zentrale Fehlerquelle"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen ein solches Netzwerk besonders?', 5, '[{"text": "Direkte Verbindung", "correct": true, "because": "Peer-zu-Peer-Datenfluss"}, {"text": "Skalierbarkeit", "correct": true, "because": "Mehr Peers, mehr Ressourcen"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Gegenteil von P2P"}, {"text": "Feste Bandbreite", "correct": false, "because": "Variiert mit Teilnehmern"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) P2P-Netzwerke verteilen Daten direkt. b) Sie benötigen immer einen Server.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, P2P ist serverlos"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung eines solchen Netzwerks?', 4, '[{"text": "Sicherheitsprotokolle", "correct": false, "because": "Schützen Daten"}, {"text": "Bandbreitenmanagement", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Netzwerke"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob P2P-Netzwerke immer für Filesharing genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Streaming oder Blockchain"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist für die Effizienz eines P2P-Netzwerks entscheidend?', 3, '[{"text": "Teilnehmerzahl", "correct": true, "because": "Mehr Peers erhöhen Ressourcen"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Nicht P2P-typisch"}, {"text": "Manuelle Verbindung", "correct": false, "because": "Automatisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen nutzen solche Netzwerke?', 5, '[{"text": "BitTorrent", "correct": true, "because": "Dezentrales Filesharing"}, {"text": "Blockchain", "correct": true, "because": "P2P für Transaktionen"}, {"text": "Webserver", "correct": false, "because": "Client-Server-Modell"}, {"text": "Datenbanken", "correct": false, "because": "Zentralisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) P2P-Netzwerke sind robust gegen Ausfälle. b) Sie sind immer unsicher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Verschlüsselung ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein P2P-Netzwerk?', 4, '[{"text": "Netzwerkprotokolle", "correct": false, "because": "Regeln Kommunikation"}, {"text": "Teilnehmer", "correct": false, "because": "Kern eines P2P-Netzwerks"}, {"text": "Zentraler Server", "correct": true, "because": "P2P ist dezentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind P2P-Netzwerke nur für private Nutzer?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Unternehmen geeignet"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei solchen Netzwerken?', 4, '[{"text": "Sicherheitsrisiken", "correct": true, "because": "Direkte Verbindungen anfällig"}, {"text": "Bandbreitenungleichheit", "correct": true, "because": "Peers haben unterschiedliche Kapazitäten"}, {"text": "Zentrale Kontrolle", "correct": false, "because": "Nicht P2P-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass P2P-Netzwerke immer illegal sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Legalität hängt von Nutzung ab"}, {"text": "Ja", "correct": false, "because": "Viele legale Anwendungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung eines P2P-Netzwerks?', 3, '[{"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schützen Daten"}, {"text": "Minimale Teilnehmer", "correct": false, "because": "Mehr Peers besser"}, {"text": "Manuelle Verbindungen", "correct": false, "because": "Automatisierung effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) P2P-Netzwerke teilen Ressourcen. b) Sie benötigen immer hohe Bandbreite.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) variiert je nach Peer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten solche Netzwerke?', 5, '[{"text": "Robustheit", "correct": true, "because": "Keine zentrale Fehlerquelle"}, {"text": "Kosteneffizienz", "correct": true, "because": "Keine Serverkosten"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Zentrale Verwaltung", "correct": false, "because": "Nicht P2P-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem P2P-Netzwerk unwichtig?', 3, '[{"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Peer-Verfügbarkeit", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob P2P-Netzwerke für Streaming geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. für Live-Übertragungen"}, {"text": "Nein", "correct": false, "because": "Streaming möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind P2P-Netzwerke immer unstrukturiert?', 3, '[{"text": "Nein", "correct": true, "because": "Strukturierte P2P wie DHT existieren"}, {"text": "Ja", "correct": false, "because": "Struktur variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem P2P-Netzwerk?', 4, '[{"text": "Dezentrale Datenverteilung", "correct": true, "because": "Typisch für P2P"}, {"text": "Zentralisierte Datenbank", "correct": false, "because": "Client-Server-Modell"}, {"text": "Lokale Netzwerkwartung", "correct": false, "because": "Nicht P2P-spezifisch"}]');
